import pandas as pd, os, glob
aps=pd.read_csv('airports.csv'); off=aps.set_index('airport')['utc_offset_hours'].to_dict(); out={}
for f in glob.glob('airlines/*.csv'):
 c=os.path.basename(f)[:-4]; df=pd.read_csv(f).drop_duplicates('flight_id')
 if c=='AS':
  s=pd.to_datetime(df.date_utc+' '+df.sched_dep_utc,errors='coerce',utc=True); a=pd.to_datetime(df.date_utc+' '+df.actual_dep_utc.fillna(''),errors='coerce',utc=True); local=s+pd.to_timedelta(df.origin.map(off),unit='h')
 else:
  s=pd.to_datetime(df.date+' '+df.sched_dep,errors='coerce'); a=pd.to_datetime(df.date+' '+df.actual_dep.fillna(''),errors='coerce'); local=s
 delay=(a-s).dt.total_seconds()/60; delay=delay.where(delay>=-720,delay+1440)
 mask=local.dt.strftime('%Y-%m').eq('2025-02') & ~df.cancelled.astype(bool) & a.notna()
 n=int(mask.sum()); k=int((mask&(delay>15)).sum()); out[c]=round(100*k/n,1)
 print(c,n,k,round(100*k/n,4),'minmax',delay[mask].min(),delay[mask].max())
print('FINAL',out)

